                            seen[ny][nx] = True; comp.append((ny, nx))
                ys = [p[0] for p in comp]; xs = [p[1] for p in comp]
                y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
                interior = [(y, x) for y in range(y0, y1+1) for x in range(x0, x1+1)
                            if (y, x) not in set(comp)]
                if interior and all(g[y][x] == bg for y, x in interior):
                    fill = 2 if len(interior) % 2 == 0 else 7
                    for y, x in interior:
                        out[y][x] = fill
    return out
result = transform(test_input)
# Final submission JSON - this is the only line
print('{"action": "submit", "grid": ' + json.dumps(result))
